function slugify($t){$m=['а'=>'a','б'=>'b','в'=>'v','г'=>'g','д'=>'d','е'=>'e','ё'=>'yo','ж'=>'zh','з'=>'z','и'=>'i','й'=>'y','к'=>'k','л'=>'l','м'=>'m','н'=>'n','о'=>'o','п'=>'p','р'=>'r','с'=>'s','т'=>'t','у'=>'u','ф'=>'f','х'=>'kh','ц'=>'ts','ч'=>'ch','ш'=>'sh','щ'=>'shch','ъ'=>'','ы'=>'y','ь'=>'','э'=>'e','ю'=>'yu','я'=>'ya'];return trim(preg_replace('/[^a-z0-9]+/','-',strtr(mb_strtolower($t),$m)),'-').'-'.substr(uniqid(),-6);}

function getArchive(){return '';}
function getDbSchema(){return 'CREATE TABLE IF NOT EXISTS `admin_users` (`id` int AUTO_INCREMENT PRIMARY KEY, `username` varchar(100) NOT NULL UNIQUE, `password_hash` varchar(255) NOT NULL, `totp_secret` varchar(64) DEFAULT NULL, `totp_enabled` tinyint(1) DEFAULT 0, `backup_codes` text, `totp_backup_codes` text, `created_at` timestamp DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS `offers` (`id` int AUTO_INCREMENT PRIMARY KEY, `title` varchar(500) NOT NULL, `slug` varchar(500) NOT NULL UNIQUE, `category` enum(\'microloans\',\'credits\',\'credit_cards\',\'debit_cards\') DEFAULT \'microloans\', `amount_min` int DEFAULT 1000, `amount_max` int DEFAULT 100000, `term_min_days` int DEFAULT 1, `term_max_days` int DEFAULT 365, `psk` decimal(10,2) DEFAULT 0, `rate` decimal(10,2) DEFAULT 0, `rate_unit` enum(\'day\',\'year\') DEFAULT \'day\', `free_term_days` int DEFAULT 0, `logo_url` text, `affiliate_url` text, `borrower_category` varchar(50) DEFAULT \'any\', `description` text, `seo_keywords` text, `regions` text, `rating` decimal(2,1) DEFAULT 5.0, `review_count` int DEFAULT 0, `is_active` tinyint(1) DEFAULT 1, `sort_order` int DEFAULT 0, `created_at` timestamp DEFAULT CURRENT_TIMESTAMP, `updated_at` timestamp DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, `age_min` int DEFAULT 18, `age_max` int DEFAULT 75, `documents` text, `requirements` text, `advantages` text, `application_time` varchar(100), `review_time` varchar(100), `payout_methods` text, `about_company` text, `meta_title` varchar(500), `meta_description` text, `features` text, `faq` text) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS `articles` (`id` int AUTO_INCREMENT PRIMARY KEY, `title` varchar(500) NOT NULL, `slug` varchar(500) NOT NULL UNIQUE, `excerpt` text, `content` text NOT NULL, `meta_title` varchar(255), `meta_description` text, `cover_image` text, `is_published` tinyint(1) DEFAULT 0, `created_at` timestamp DEFAULT CURRENT_TIMESTAMP, `updated_at` timestamp DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS `reviews` (`id` int AUTO_INCREMENT PRIMARY KEY, `offer_id` int NOT NULL, `author_name` varchar(255) NOT NULL, `rating` int DEFAULT 5, `text` text NOT NULL, `pros` text, `cons` text, `is_approved` tinyint(1) DEFAULT 1, `created_at` timestamp DEFAULT CURRENT_TIMESTAMP, KEY `offer_id` (`offer_id`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS `click_stats` (`id` int AUTO_INCREMENT PRIMARY KEY, `offer_id` int NOT NULL, `user_agent` text, `referer` text, `ip` varchar(50), `utm_source` varchar(255), `utm_medium` varchar(255), `utm_campaign` varchar(255), `utm_content` varchar(255), `utm_term` varchar(255), `page_from` text, `ab_variant_id` int, `created_at` timestamp DEFAULT CURRENT_TIMESTAMP, KEY `offer_id` (`offer_id`), KEY `created_at` (`created_at`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS `subscribers` (`id` int AUTO_INCREMENT PRIMARY KEY, `email` varchar(255) NOT NULL UNIQUE, `is_active` tinyint(1) DEFAULT 1, `source` varchar(100), `created_at` timestamp DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS `geo_redirects` (`id` int AUTO_INCREMENT PRIMARY KEY, `city_name` varchar(255) NOT NULL, `slug` varchar(255) NOT NULL UNIQUE, `region` varchar(255), `is_active` tinyint(1) DEFAULT 1) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS `offer_tags` (`id` int AUTO_INCREMENT PRIMARY KEY, `slug` varchar(255) NOT NULL UNIQUE, `title` varchar(255) NOT NULL, `h1` varchar(500), `description` text, `meta_description` text, `content` text, `icon` varchar(10), `category` enum(\'microloans\',\'credits\',\'credit_cards\',\'debit_cards\') DEFAULT \'microloans\', `features` text, `is_active` tinyint(1) DEFAULT 1, `sort_order` int DEFAULT 0, `search_queries` text, `created_at` timestamp DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS `offer_tag_links` (`id` int AUTO_INCREMENT PRIMARY KEY, `offer_id` int NOT NULL, `tag_id` int NOT NULL, UNIQUE KEY `offer_tag` (`offer_id`,`tag_id`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS `categories` (`id` int AUTO_INCREMENT PRIMARY KEY, `slug` varchar(255) NOT NULL UNIQUE, `name` varchar(255) NOT NULL, `title` varchar(500), `description` text, `meta_title` varchar(500), `meta_description` text, `icon` varchar(50), `parent_id` int, `category_type` enum(\'microloans\',\'credits\',\'credit_cards\',\'debit_cards\') DEFAULT \'microloans\', `filter_json` text, `content_top` text, `content_bottom` text, `is_active` tinyint(1) DEFAULT 1, `sort_order` int DEFAULT 0, `footer_section` varchar(50) DEFAULT NULL, `created_at` timestamp DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS `page_views` (`id` int AUTO_INCREMENT PRIMARY KEY, `page` varchar(500) NOT NULL, `ip` varchar(50), `utm_source` varchar(255), `utm_medium` varchar(255), `utm_campaign` varchar(255), `created_at` timestamp DEFAULT CURRENT_TIMESTAMP, KEY `created_at` (`created_at`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS `admin_login_log` (`id` int AUTO_INCREMENT PRIMARY KEY, `username` varchar(100), `ip` varchar(50), `user_agent` text, `success` tinyint(1) DEFAULT 0, `created_at` timestamp DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS `admin_ip_whitelist` (`id` int AUTO_INCREMENT PRIMARY KEY, `ip` varchar(50) NOT NULL UNIQUE, `description` varchar(255), `created_at` timestamp DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS `admin_audit_log` (`id` int AUTO_INCREMENT PRIMARY KEY, `admin_id` int, `admin_name` varchar(100), `action` varchar(50) NOT NULL, `entity` varchar(50) NOT NULL, `entity_id` int, `entity_name` varchar(255), `changes` text, `ip` varchar(45), `user_agent` varchar(500), `created_at` timestamp DEFAULT CURRENT_TIMESTAMP, KEY `idx_entity` (`entity`,`entity_id`), KEY `idx_created` (`created_at`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS `city_seo_texts` (`id` int AUTO_INCREMENT PRIMARY KEY, `city_slug` varchar(255) NOT NULL, `page_type` varchar(50) NOT NULL, `h1` varchar(500), `title` varchar(500), `description` text, `content` text, `faq` text, `created_at` timestamp DEFAULT CURRENT_TIMESTAMP, UNIQUE KEY `city_page` (`city_slug`,`page_type`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS `users` (`id` int AUTO_INCREMENT PRIMARY KEY, `email` varchar(255) NOT NULL UNIQUE, `phone` varchar(20), `password_hash` varchar(255) NOT NULL, `name` varchar(255), `is_active` tinyint(1) DEFAULT 1, `created_at` timestamp DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS `user_favorites` (`id` int AUTO_INCREMENT PRIMARY KEY, `user_id` int NOT NULL, `offer_id` int NOT NULL, UNIQUE KEY `user_offer` (`user_id`,`offer_id`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS `user_applications` (`id` int AUTO_INCREMENT PRIMARY KEY, `user_id` int NOT NULL, `offer_id` int NOT NULL, `click_stat_id` int, `ip` varchar(50), `created_at` timestamp DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS `user_login_log` (`id` int AUTO_INCREMENT PRIMARY KEY, `user_id` int, `email` varchar(255), `ip` varchar(45), `success` tinyint(1) DEFAULT 0, `created_at` timestamp DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS `postback_conversions` (`id` int AUTO_INCREMENT PRIMARY KEY, `click_id` varchar(255), `transaction_id` varchar(255), `offer_id` int, `external_offer_id` varchar(100), `status` varchar(50) NOT NULL, `payout` decimal(10,2) DEFAULT 0, `ip` varchar(45), `aff_sub` varchar(500), `aff_sub2` varchar(500), `aff_sub3` varchar(500), `goal_id` varchar(100), `raw_query` text, `created_at` timestamp DEFAULT CURRENT_TIMESTAMP, KEY `idx_click_id` (`click_id`), KEY `idx_status` (`status`), KEY `idx_offer_id` (`offer_id`), KEY `idx_created_at` (`created_at`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS `postback_profiles` (`id` int AUTO_INCREMENT PRIMARY KEY, `name` varchar(255) NOT NULL, `type` varchar(50) DEFAULT \'leads_su\', `config` text, `is_active` tinyint(1) DEFAULT 1, `created_at` timestamp DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS `ab_tests` (`id` int AUTO_INCREMENT PRIMARY KEY, `name` varchar(255) NOT NULL, `offer_id` int, `scope` enum(\'offer\',\'global\') DEFAULT \'offer\', `is_active` tinyint(1) DEFAULT 0, `created_at` timestamp DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS `ab_variants` (`id` int AUTO_INCREMENT PRIMARY KEY, `test_id` int NOT NULL, `name` varchar(255) NOT NULL, `button_text` varchar(255), `button_color` varchar(50), `cta_text` text, `weight` int DEFAULT 50, `views` int DEFAULT 0, `clicks` int DEFAULT 0) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS `newsletters` (`id` int AUTO_INCREMENT PRIMARY KEY, `subject` varchar(500) NOT NULL, `content` text NOT NULL, `status` enum(\'draft\',\'scheduled\',\'sending\',\'sent\') DEFAULT \'draft\', `scheduled_at` datetime, `sent_at` datetime, `sent_count` int DEFAULT 0, `created_at` timestamp DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS `newsletter_send_log` (`id` int AUTO_INCREMENT PRIMARY KEY, `newsletter_id` int NOT NULL, `subscriber_id` int NOT NULL, `email` varchar(255) NOT NULL, `status` varchar(20) DEFAULT \'sent\', `sent_at` timestamp DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS `newsletter_events` (`id` int AUTO_INCREMENT PRIMARY KEY, `newsletter_id` int NOT NULL, `subscriber_id` int, `event_type` enum(\'open\',\'click\') NOT NULL, `url` text, `ip` varchar(45), `user_agent` varchar(500), `created_at` timestamp DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS `offer_link_checks` (`id` int AUTO_INCREMENT PRIMARY KEY, `offer_id` int NOT NULL, `url` text NOT NULL, `status_code` int, `redirect_url` text, `response_time_ms` int, `error` text, `checked_at` timestamp DEFAULT CURRENT_TIMESTAMP, KEY `offer_id` (`offer_id`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4';}

if ($step === 'install' && $_SERVER['REQUEST_METHOD'] === 'POST') {
    $dbHost = trim($_POST['db_host'] ?? 'localhost');
    $dbName = trim($_POST['db_name'] ?? '');
    $dbUser = trim($_POST['db_user'] ?? '');
    $dbPass = $_POST['db_pass'] ?? '';
    $adminUser = trim($_POST['admin_user'] ?? 'admin');
    $adminPass = $_POST['admin_pass'] ?? '';
    $siteName = trim($_POST['site_name'] ?? 'Космозайм');
    $siteUrl = rtrim(trim($_POST['site_url'] ?? ''), '/');
    
    if (!$dbName || !$dbUser) $error = 'Заполните данные БД';
    elseif (strlen($adminPass) < 6) $error = 'Пароль мин. 6 символов';
    elseif (!$siteUrl) $error = 'Укажите URL сайта';
    else {
        try {
            // 1. Распаковка
            $tmp = __DIR__ . '/_kosmo_tmp.tar.gz';
            file_put_contents($tmp, base64_decode(getArchive()));
            shell_exec('cd ' . escapeshellarg(__DIR__) . ' && tar xzf _kosmo_tmp.tar.gz 2>&1');
            if (!file_exists(__DIR__ . '/index.php') && class_exists('PharData')) {
                $phar = new PharData($tmp); $phar->extractTo(__DIR__, null, true);
            }
            @unlink($tmp);
            if (!file_exists(__DIR__ . '/index.php')) throw new Exception('Файлы не распакованы');
            
            // 2. Директории
            foreach (['data','data/cache','data/geo_cache','images/articles','images/offer'] as $d)
                @mkdir(__DIR__ . '/' . $d, 0755, true);
            
            // 3. .htaccess
            file_put_contents(__DIR__ . '/.htaccess', "AddDefaultCharset UTF-8\n\nRewriteEngine On\nRewriteCond %{REQUEST_FILENAME} !-f\nRewriteCond %{REQUEST_FILENAME} !-d\nRewriteRule ^(.*)\$ index.php [QSA,L]\n\n<IfModule mod_expires.c>\nExpiresActive On\nExpiresByType image/jpeg \"access plus 1 month\"\nExpiresByType image/png \"access plus 1 month\"\nExpiresByType image/svg+xml \"access plus 1 month\"\nExpiresByType text/css \"access plus 1 week\"\nExpiresByType application/javascript \"access plus 1 week\"\n</IfModule>\n\n<IfModule mod_deflate.c>\nAddOutputFilterByType DEFLATE text/html text/css application/javascript application/json image/svg+xml\n</IfModule>\n\n<FilesMatch \"\\.(env|log|json|txt)\$\">\n<IfModule mod_authz_core.c>\nRequire all denied\n</IfModule>\n</FilesMatch>\n\n<FilesMatch \"^\\.\">\n<IfModule mod_authz_core.c>\nRequire all denied\n</IfModule>\n</FilesMatch>\n");
            
            // 4. .env
            file_put_contents(__DIR__ . '/.env', "DB_HOST=$dbHost\nDB_NAME=$dbName\nDB_USER=$dbUser\nDB_PASS=$dbPass\nNEXT_PUBLIC_SITE_URL=$siteUrl\nSESSION_SECRET=" . bin2hex(random_bytes(32)) . "\nCRON_SECRET=" . bin2hex(random_bytes(16)) . "\n");
            @chmod(__DIR__ . '/.env', 0600);
            
            // 5. config.php — подменяем домен и убираем старые fallback
            $cfg = file_get_contents(__DIR__ . '/config.php');
            $cfg = str_replace("'https://kosmozaim.ru'", "'" . $siteUrl . "'", $cfg);
            $cfg = str_replace("'partnerka72_kosmonew'", "''", $cfg);
            $cfg = str_replace("'partnerka72'", "''", $cfg);
            file_put_contents(__DIR__ . '/config.php', $cfg);
            
            // 6. site-settings.json
            file_put_contents(__DIR__ . '/data/site-settings.json', json_encode(['site_name' => $siteName, 'site_url' => $siteUrl], JSON_PRETTY_PRINT | JSON_UNESCAPED_UNICODE));
            
            // 7. БД — ВСЕ таблицы
            $pdo = new PDO("mysql:host=$dbHost;charset=utf8mb4", $dbUser, $dbPass, [PDO::ATTR_ERRMODE => PDO::ERRMODE_EXCEPTION]);
            $pdo->exec("CREATE DATABASE IF NOT EXISTS `$dbName` CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci");
            $pdo->exec("USE `$dbName`");
            foreach (array_filter(array_map('trim', preg_split('/;\s*[\r\n]+/', getDbSchema()))) as $q) {
                if ($q && $q[0] !== '-') $pdo->exec($q);
            }
            
            // Админ
            $pdo->prepare("INSERT INTO admin_users (username, password_hash) VALUES (?, ?) ON DUPLICATE KEY UPDATE password_hash=VALUES(password_hash)")
                ->execute([$adminUser, password_hash($adminPass, PASSWORD_DEFAULT)]);
            
            // Категории (как на основном сайте)
            $cats = [
                ['zajmy','Займы','Займы онлайн','microloans',1,'products'],
                ['kredity','Кредиты','Кредиты наличными','credits',2,'products'],
                ['karty-kreditnye','Кредитные карты','Кредитные карты','credit_cards',3,'products'],
                ['karty-debetovye','Дебетовые карты','Дебетовые карты','debit_cards',4,'products'],
                ['calculator','Калькулятор','Кредитный калькулятор','microloans',1,'tools'],
                ['compare','Сравнение','Сравнение предложений','microloans',2,'tools'],
                ['articles','Статьи','Финансовые статьи','microloans',3,'tools'],
            ];
            $st = $pdo->prepare("INSERT IGNORE INTO categories (slug,name,title,category_type,sort_order,footer_section,is_active) VALUES (?,?,?,?,?,?,1)");
            foreach ($cats as $c) $st->execute($c);
            
            // Теги
            $tags = [['bez-otkaza','Займы без отказа','✅','microloans'],['bez-protsentov','Займы без процентов','🆓','microloans'],['na-kartu','Займы на карту','💳','microloans'],['s-plohoj-ki','С плохой КИ','📊','microloans'],['dlya-pensionerov','Для пенсионеров','👴','microloans'],['studentam','Для студентов','🎓','microloans']];
            $st = $pdo->prepare("INSERT IGNORE INTO offer_tags (slug,title,icon,category,is_active,sort_order) VALUES (?,?,?,?,1,?)");
            foreach ($tags as $i => $t) $st->execute([$t[0],$t[1],$t[2],$t[3],$i+1]);
            
            // Демо-офферы
            $offers = [['Пример МФО 1','microloans',1000,30000,0.8,'day',14],['Пример МФО 2','microloans',5000,100000,0.99,'day',7],['Пример Банк','credits',50000,5000000,15.9,'year',0],['Пример Карта','credit_cards',0,500000,24.9,'year',55]];
            $st = $pdo->prepare("INSERT INTO offers (title,slug,category,amount_min,amount_max,rate,rate_unit,free_term_days,affiliate_url,is_active,sort_order) VALUES (?,?,?,?,?,?,?,?,'',1,?)");
            foreach ($offers as $i => $o) $st->execute([$o[0],slugify($o[0]),$o[1],$o[2],$o[3],$o[4],$o[5],$o[6],$i+1]);
            $pdo->exec("INSERT IGNORE INTO offer_tag_links (offer_id,tag_id) SELECT o.id,t.id FROM offers o,offer_tags t WHERE o.category='microloans' AND t.category='microloans'");
            
            // Города
            $cities = [['Москва','moskva','Московская область'],['Санкт-Петербург','sankt-peterburg','Ленинградская область'],['Новосибирск','novosibirsk','Новосибирская область'],['Екатеринбург','ekaterinburg','Свердловская область'],['Казань','kazan','Республика Татарстан'],['Нижний Новгород','nizhnij-novgorod','Нижегородская область'],['Челябинск','chelyabinsk','Челябинская область'],['Самара','samara','Самарская область'],['Омск','omsk','Омская область'],['Ростов-на-Дону','rostov-na-donu','Ростовская область']];
            $st = $pdo->prepare("INSERT IGNORE INTO geo_redirects (city_name,slug,region,is_active) VALUES (?,?,?,1)");
            foreach ($cities as $c) $st->execute($c);
            
            $step = 'done';
        } catch (Exception $e) { $error = $e->getMessage(); @unlink(__DIR__ . '/_kosmo_tmp.tar.gz'); }
    }
}
?>
